class Solution {
    fun findThePrefixCommonArray(A:IntArray,B:IntArray):IntArray{
        val n=A.size;
        val seenA=BooleanArray(n+1);
        val seenB=BooleanArray(n+1);
        val answer=IntArray(n);
        var common=0;
        for(i in 0 until n){
            seenA[A[i]]=true;
            if(seenB[A[i]])common++;
            seenB[B[i]]=true;
            if(seenA[B[i]])common++;
            answer[i]=common
        };
        return answer
    }
}

